    const specDir = `${tempDir}/.kspec`;
    // Use inbox list (read-only, always succeeds) to verify the env var works
    const result = kspec("inbox list", tempDir, {
      env: { KSPEC_SPEC_DIR: specDir },
    });
    expect(result.exitCode).toBe(0);
  });
});

