  it("atomic mode: failure → all changes rolled back", () => {
    const result = kspecJson<BatchExecResult>(
      `batch --commands '[{"command":"inbox add","args":{"text":"should-not-persist"}},{"command":"task start","args":{"ref":"@nonexistent-task"}}]'`,
